const base = "https://api.example.com/v1/articles";

await fetch(base);                                     // GET: list
await fetch(`${base}/42`, { method: "HEAD" });         // headers only

await fetch(base, {                                    // POST: create in collection
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ title: "Hello" }),
});

await fetch(`${base}/42`, {                            // PUT: replace whole resource
  method: "PUT",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ title: "Hello", body: "...", tags: [] }),
});

await fetch(`${base}/42`, {                            // PATCH: change one field
  method: "PATCH",
  headers: { "Content-Type": "application/merge-patch+json" },
  body: JSON.stringify({ title: "Hello again" }),
});

await fetch(`${base}/42`, { method: "DELETE" });       // idempotent: safe to retry

import http from "node:http";

const server = http.createServer((req, res) => {
  if (req.url === "/old") { res.writeHead(301, { Location: "/new" }); return res.end(); }
  if (req.url === "/new") { res.writeHead(200, { "Content-Type": "text/plain" }); return res.end("hi"); }
  if (req.url === "/admin") { res.writeHead(403); return res.end(); }
  res.writeHead(404, { "Content-Type": "text/plain" }); res.end("not found");
});

server.listen(0, async () => {
  const base = `http://localhost:${server.address().port}`;
  for (const p of ["/old", "/admin", "/nope"]) {
    const r = await fetch(base + p, { redirect: "manual" });
    console.log(p, r.status, r.headers.get("location"));
  }
  // /old 301 /new
  // /admin 403 null
  // /nope 404 null
  server.close();
});

// JSON body: set the header AND serialise
await fetch("https://httpbin.org/post", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ name: "Ada", langs: ["en", "fr"] }),
});

// URL-encoded form body (fetch sets the Content-Type for URLSearchParams)
await fetch("https://httpbin.org/post", {
  method: "POST",
  body: new URLSearchParams({ name: "Ada Lovelace", lang: "en" }),  // name=Ada+Lovelace&lang=en
});

// Multipart with a file (fetch sets multipart/form-data with a boundary)
const form = new FormData();
form.append("title", "Avatar");
form.append("file", new Blob(["fake png bytes"], { type: "image/png" }), "a.png");
const res = await fetch("https://httpbin.org/post", { method: "POST", body: form });
console.log(res.headers.get("content-type"));   // application/json

import http from "node:http";

const server = http.createServer((req, res) => {
  if (req.url === "/login") {
    res.setHeader("Set-Cookie",
      "__Host-session=r4nd0m1d; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=3600");
    return res.end("logged in");
  }
  res.end(`you sent: ${req.headers.cookie ?? "no cookie"}`);
});

server.listen(0, async () => {
  const base = `http://localhost:${server.address().port}`;
  const r = await fetch(base + "/login");
  console.log(r.headers.get("set-cookie"));
  // __Host-session=r4nd0m1d; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=3600
  const r2 = await fetch(base + "/me", { headers: { Cookie: "__Host-session=r4nd0m1d" } });
  console.log(await r2.text());   // you sent: __Host-session=r4nd0m1d
  server.close();
});

import http from "node:http";
import { createHash } from "node:crypto";

const body = JSON.stringify({ price: 12 });
const etag = `"${createHash("sha1").update(body).digest("hex").slice(0, 8)}"`;

const server = http.createServer((req, res) => {
  res.setHeader("Cache-Control", "no-cache");   // reuse only after revalidating
  res.setHeader("ETag", etag);
  if (req.headers["if-none-match"] === etag) { res.statusCode = 304; return res.end(); }
  res.setHeader("Content-Type", "application/json");
  res.end(body);
});

server.listen(0, async () => {
  const url = `http://localhost:${server.address().port}/price`;
  const first = await fetch(url);
  console.log(first.status, first.headers.get("etag"));          // 200 "<hash>"
  const again = await fetch(url, { headers: { "If-None-Match": etag } });
  console.log(again.status, (await again.text()).length);         // 304 0
  server.close();
});

import http from "node:http";

const ALLOWED = new Set(["https://app.example.com"]);

const server = http.createServer((req, res) => {
  const origin = req.headers.origin;
  if (ALLOWED.has(origin)) {
    res.setHeader("Access-Control-Allow-Origin", origin);
    res.setHeader("Access-Control-Allow-Credentials", "true");
    res.setHeader("Vary", "Origin");
  }
  if (req.method === "OPTIONS") {                       // preflight
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
    res.setHeader("Access-Control-Max-Age", "600");
    res.statusCode = 204; return res.end();
  }
  res.setHeader("Content-Type", "application/json");
  res.end(JSON.stringify({ ok: true }));
});
server.listen(8080);

