import http from "node:http";

// SSE server: one long-lived response, events as text lines
const server = http.createServer((req, res) => {
  res.writeHead(200, { "Content-Type": "text/event-stream", "Cache-Control": "no-cache" });
  let n = 0;
  const timer = setInterval(() => {
    n++;
    res.write(`id: ${n}\nevent: tick\ndata: ${JSON.stringify({ n })}\n\n`);
    if (n === 3) { clearInterval(timer); res.end(); }
  }, 100);
});

server.listen(0, async () => {
  const res = await fetch(`http://localhost:${server.address().port}/events`);
  console.log(await res.text());
  // id: 1 / event: tick / data: {"n":1}   ... three events, blank-line separated
  server.close();
});

