import http from "node:http";
import { randomBytes } from "node:crypto";

http.createServer((req, res) => {
  const nonce = randomBytes(16).toString("base64");
  res.setHeader("Strict-Transport-Security", "max-age=63072000; includeSubDomains");
  res.setHeader("Content-Security-Policy",
    `script-src 'nonce-${nonce}' 'strict-dynamic'; object-src 'none'; ` +
    `base-uri 'none'; frame-ancestors 'none'`);
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
  res.setHeader("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.end(`<!doctype html><title>Safe</title>
<script nonce="${nonce}">console.log("allowed")</script>
<script>console.log("blocked by CSP")</script>`);
}).listen(8080);

// Client: safe retry of a POST with an idempotency key and backoff
import { randomUUID } from "node:crypto";

async function createPayment(body, attempts = 4) {
  const key = randomUUID();                      // same key for every retry
  for (let i = 0; i < attempts; i++) {
    try {
      const res = await fetch("https://api.example.com/v1/payments", {
        method: "POST",
        headers: { "Content-Type": "application/json", "Idempotency-Key": key },
        body: JSON.stringify(body),
      });
      if (res.status !== 429 && res.status < 500) return res;   // done (or a 4xx to fix)
      const wait = Number(res.headers.get("retry-after")) * 1000 || 2 ** i * 250;
      await new Promise((r) => setTimeout(r, wait + Math.random() * 100));
    } catch {                                     // network error: retry is safe
      await new Promise((r) => setTimeout(r, 2 ** i * 250));
    }
  }
  throw new Error("payment failed after retries");
}
